    45	      subject: `${subjectPrefix}${formatted.title}`,
    46	      text: `${formatted.body}\n\n${footer}`,
    47	      html: `<h1>${this.escapeHtml(formatted.title)}</h1><p>${this.escapeHtml(formatted.body)}</p><footer>${this.escapeHtml(footer)}</footer>`,
    48	      preview: formatted.body.slice(0, 90)
    49	    };
    50	  }
    51	
    52	  footerFor(user, message) {
    53	    if (message.category === 'transactional' || message.category === 'security') {
