     1	class Notifier {
     2	  constructor(options = {}) {
     3	    if (new.target === Notifier) {
     4	      throw new TypeError('Notifier is abstract');
     5	    }
     6	
     7	    this.channel = options.channel;
     8	    this.transport = options.transport || {};
     9	    this.templates = options.templates || {};
    10	    this.throttleStore = options.throttleStore || new Map();
    11	    this.now = options.now || (() => new Date());
    12	    this.defaultSender = options.defaultSender || 'Product Team';
    13	    this.defaultLocale = options.defaultLocale || 'en-US';
    14	    this.maxPerHour = options.maxPerHour || 3;
    15	  }
    16	
    17	  async send(user, message, options = {}) {
    18	    this.validateUser(user);
    19	    this.validateMessage(message);
    20	
    21	    const throttle = this.shouldThrottle(user, message, options);
    22	    if (throttle.throttled) {
    23	      return {
    24	        channel: this.channel,
    25	        status: 'throttled',
    26	        reason: throttle.reason,
    27	        retryAt: throttle.retryAt,
    28	        userId: user.id
    29	      };
    30	    }
    31	
    32	    const formatted = this.format(user, message, options);
    33	    await this.deliver(formatted, user, message, options);
    34	    this.recordDelivery(user, message, options);
    35	
    36	    return {
    37	      channel: this.channel,
    38	      status: 'sent',
    39	      userId: user.id,
    40	      id: formatted.id,
    41	      preview: formatted.preview
    42	    };
    43	  }
    44	
    45	  validateUser(user) {
    46	    if (!user || typeof user !== 'object') {
    47	      throw new TypeError('user is required');
    48	    }
    49	    if (!user.id) {
    50	      throw new TypeError('user.id is required');
    51	    }
    52	  }
    53	
    54	  validateMessage(message) {
    55	    if (!message || typeof message !== 'object') {
    56	      throw new TypeError('message is required');
    57	    }
    58	    if (!message.title || !message.body) {
    59	      throw new TypeError('message.title and message.body are required');
    60	    }
    61	  }
    62	
    63	  shouldThrottle(user, message, options = {}) {
    64	    if (options.force || message.priority === 'urgent') {
    65	      return { throttled: false };
    66	    }
    67	
    68	    const key = this.throttleKey(user, message);
    69	    const now = this.now().getTime();
    70	    const windowMs = 60 * 60 * 1000;
    71	    const records = (this.throttleStore.get(key) || []).filter(ts => now - ts < windowMs);
    72	
    73	    if (records.length >= this.maxPerHour) {
    74	      return {
    75	        throttled: true,
    76	        reason: `${this.channel} hourly limit reached`,
    77	        retryAt: new Date(records[0] + windowMs).toISOString()
    78	      };
    79	    }
    80	
    81	    return { throttled: false };
    82	  }
    83	
    84	  throttleKey(user, message) {
    85	    const category = message.category || 'general';
    86	    return `${this.channel}:${user.id}:${category}`;
    87	  }
    88	
    89	  format(user, message, options = {}) {
    90	    const id = `${this.channel}-${user.id}-${this.now().getTime()}`;
    91	    const locale = options.locale || user.locale || this.defaultLocale;
    92	    const title = this.applyTemplate(message.title, user, message);
    93	    const body = this.applyTemplate(message.body, user, message);
    94	
    95	    return {
    96	      id,
    97	      channel: this.channel,
    98	      locale,
    99	      title,
   100	      body,
   101	      preview: `${title}: ${body}`.slice(0, 120),
   102	      metadata: {
   103	        category: message.category || 'general',
   104	        priority: message.priority || 'normal',
   105	        generatedAt: this.now().toISOString()
   106	      }
   107	    };
   108	  }
   109	
   110	  applyTemplate(value, user, message) {
   111	    return String(value)
   112	      .replace(/\{\{name\}\}/g, user.name || 'there')
   113	      .replace(/\{\{id\}\}/g, user.id)
   114	      .replace(/\{\{category\}\}/g, message.category || 'general');
   115	  }
   116	
   117	  recordDelivery(user, message) {
   118	    const key = this.throttleKey(user, message);
   119	    const records = this.throttleStore.get(key) || [];
   120	    records.push(this.now().getTime());
   121	    this.throttleStore.set(key, records);
   122	  }
   123	
   124	  async deliver() {
   125	    throw new Error(`${this.channel} deliver() must be implemented`);
   126	  }
   127	}
   128	
   129	module.exports = Notifier;
