// Golden-master harness: node characterize.js <path/to/src/notifications> > out.json
const path = require('node:path');
const util = require('node:util');

const target = path.resolve(process.argv[2]);
const lib = require(target);
const { createNotifier, createAllNotifiers, registry } = lib;

const CHANNELS = ['email', 'sms', 'slack', 'inapp'];
const START = '2026-01-02T03:04:05.000Z';

const validUsers = {
  email: { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: true },
  sms: { id: 'u2', name: 'Bo', phone: '+15551234567', smsOptIn: true },
  slack: { id: 'u3', name: 'Cy', slackId: 'U123' },
  inapp: { id: 'u4', name: 'Dee' }
};

function clock(startIso = START) {
  let current = new Date(startIso).getTime();
  const fn = () => {
    fn.calls += 1;
    return new Date(current);
  };
  fn.calls = 0;
  fn.advance = ms => { current += ms; };
  return fn;
}

// Methods read `this`, so a detached call would fail loudly.
function methodTransport() {
  const t = {
    calls: [],
    push(name, payload) { this.calls.push([name, JSON.stringify(payload)]); return 'transport-return'; },
    async email(payload) { return this.push('email', payload); },
    async sms(payload) { return this.push('sms', payload); },
    async slack(payload) { return this.push('slack', payload); },
    async inapp(payload) { return this.push('inapp', payload); }
  };
  return t;
}

function errorShape(err) {
  return { error: { ctor: err && err.constructor && err.constructor.name, message: err && err.message } };
}

async function capture(fn) {
  try {
    const value = await fn();
    return { value: value === undefined ? '<undefined>' : JSON.parse(JSON.stringify(value)) };
  } catch (err) {
    return errorShape(err);
  }
}

function captureSync(fn) {
  try {
    const value = fn();
    return { value: value === undefined ? '<undefined>' : JSON.parse(JSON.stringify(value)) };
  } catch (err) {
    return errorShape(err);
  }
}

function storeDump(store) {
  return [...store.entries()].map(([k, v]) => [k, [...v]]);
}

function env(channel, extra = {}) {
  const now = clock();
  const transport = methodTransport();
  const throttleStore = new Map();
  const notifier = createNotifier(channel, { transport, throttleStore, now, ...extra });
  return { now, transport, throttleStore, notifier };
}

const scenarios = {};
function scenario(name, fn) {
  scenarios[name] = fn;
}

