// Golden-master harness: node characterize.js <path/to/src/notifications> > out.json
const path = require('node:path');
const util = require('node:util');

const target = path.resolve(process.argv[2]);
const lib = require(target);
const { createNotifier, createAllNotifiers, registry } = lib;

const CHANNELS = ['email', 'sms', 'slack', 'inapp'];
const START = '2026-01-02T03:04:05.000Z';

const validUsers = {
  email: { id: 'u1', name: 'Ava', email: 'ava@example.com', emailOptIn: true },
  sms: { id: 'u2', name: 'Bo', phone: '+15551234567', smsOptIn: true },
  slack: { id: 'u3', name: 'Cy', slackId: 'U123' },
  inapp: { id: 'u4', name: 'Dee' }
};

function clock(startIso = START) {
  let current = new Date(startIso).getTime();
  const fn = () => {
    fn.calls += 1;
    return new Date(current);
  };
  fn.calls = 0;
  fn.advance = ms => { current += ms; };
  return fn;
}

// Methods read `this`, so a detached call would fail loudly.
function methodTransport() {
  const t = {
    calls: [],
    push(name, payload) { this.calls.push([name, JSON.stringify(payload)]); return 'transport-return'; },
    async email(payload) { return this.push('email', payload); },
    async sms(payload) { return this.push('sms', payload); },
    async slack(payload) { return this.push('slack', payload); },
    async inapp(payload) { return this.push('inapp', payload); }
  };
  return t;
}

function errorShape(err) {
  return { error: { ctor: err && err.constructor && err.constructor.name, message: err && err.message } };
}

async function capture(fn) {
  try {
    const value = await fn();
    return { value: value === undefined ? '<undefined>' : JSON.parse(JSON.stringify(value)) };
  } catch (err) {
    return errorShape(err);
  }
}

function captureSync(fn) {
  try {
    const value = fn();
    return { value: value === undefined ? '<undefined>' : JSON.parse(JSON.stringify(value)) };
  } catch (err) {
    return errorShape(err);
  }
}

function storeDump(store) {
  return [...store.entries()].map(([k, v]) => [k, [...v]]);
}

function env(channel, extra = {}) {
  const now = clock();
  const transport = methodTransport();
  const throttleStore = new Map();
  const notifier = createNotifier(channel, { transport, throttleStore, now, ...extra });
  return { now, transport, throttleStore, notifier };
}

const scenarios = {};
function scenario(name, fn) {
  scenarios[name] = fn;
}

// ---------- validation ----------
const badUsers = [undefined, null, 'u', 42, {}, { id: '' }, { id: 0 }];
const badMessages = [undefined, null, 'm', {}, { title: 'T' }, { body: 'B' }, { title: '', body: 'B' }, { title: 'T', body: 0 }];
for (const channel of CHANNELS) {
  scenario(`validation/base-user/${channel}`, async () => {
    const out = [];
    for (const user of badUsers) {
      const { notifier } = env(channel);
      out.push(await capture(() => notifier.send(user, { title: 'T', body: 'B' })));
    }
    return out;
  });
  scenario(`validation/base-message/${channel}`, async () => {
    const out = [];
    for (const message of badMessages) {
      const { notifier } = env(channel);
      out.push(await capture(() => notifier.send(validUsers[channel], message)));
    }
    return out;
  });
  scenario(`validation/user-before-message/${channel}`, async () => {
    const { notifier } = env(channel);
    return capture(() => notifier.send({ id: 'x' }, null));
  });
  scenario(`validation/send-is-async-rejection/${channel}`, async () => {
    const { notifier } = env(channel);
    let syncThrow = false;
    let promise;
    try {
      promise = notifier.send(null, null);
    } catch (err) {
      syncThrow = true;
    }
    const rejected = await capture(() => promise);
    return { syncThrow, isPromise: promise instanceof Promise, rejected };
  });
}

scenario('validation/email-channel', async () => {
  const users = [
    { id: 'e' }, { id: 'e', email: '' }, { id: 'e', email: 'no-at-sign' }, { id: 'e', email: 5 },
    { id: 'e', email: '@' }, { id: 'e', email: 'a@b' }
  ];
  const out = [];
  for (const user of users) {
    const { notifier } = env('email');
    out.push(await capture(() => notifier.send(user, { title: 'T', body: 'B' })));
  }
  return out;
});

scenario('validation/sms-channel', async () => {
  const phones = [undefined, '', '555-1212', '+0123456789', '+123456', '+1234567', '+123456789012345',
    '+1234567890123456', '15551234567', '+1 5551234567', ' +15551234567', '+15551234567\n', 15551234567];
  const out = [];
  for (const phone of phones) {
    const { notifier } = env('sms');
    out.push([String(phone), await capture(() => notifier.send({ id: 's', phone }, { title: 'T', body: 'B' }))]);
  }
  return out;
});

scenario('validation/slack-channel', async () => {
  const users = [{ id: 'k' }, { id: 'k', slackId: '' }, { id: 'k', slackChannel: '#c' }, { id: 'k', slackId: 'U9' }];
  const out = [];
  for (const user of users) {
    const { notifier } = env('slack');
    out.push(await capture(() => notifier.send(user, { title: 'T', body: 'B' })));
  }
  return out;
});

scenario('validation/inapp-channel', async () => {
  const users = [{ id: 'i', disabledInApp: true }, { id: 'i', disabledInApp: 0 }, { id: 'i', disabledInApp: 'yes' }];
  const out = [];
  for (const user of users) {
    const { notifier } = env('inapp');
    out.push(await capture(() => notifier.send(user, { title: 'T', body: 'B' })));
  }
  return out;
});

// ---------- throttling ----------
for (const channel of CHANNELS) {
  scenario(`throttle/default-limit-and-retryAt/${channel}`, async () => {
    const { notifier, now, transport, throttleStore } = env(channel);
    const out = [];
    for (let i = 0; i < 52; i += 1) {
      const r = await capture(() => notifier.send(validUsers[channel], { title: 'T', body: `B${i}`, category: 'digest' }));
      out.push(r.value ? r.value.status + (r.value.retryAt ? `@${r.value.retryAt}` : '') : r);
      now.advance(1000);
    }
    return { out, transportCalls: transport.calls.length, store: storeDump(throttleStore) };
  });

  scenario(`throttle/custom-limit-window-expiry/${channel}`, async () => {
    const { notifier, now, throttleStore } = env(channel, { maxPerHour: 2 });
    const user = validUsers[channel];
    const msg = { title: 'T', body: 'B', category: 'digest' };
    const out = [];
    out.push(await capture(() => notifier.send(user, msg)));
    now.advance(10 * 60 * 1000);
    out.push(await capture(() => notifier.send(user, msg)));
    now.advance(10 * 60 * 1000);
    out.push(await capture(() => notifier.send(user, msg)));
    now.advance(40 * 60 * 1000 - 1);
    out.push(await capture(() => notifier.send(user, msg)));
    now.advance(1);
    out.push(await capture(() => notifier.send(user, msg)));
    out.push(await capture(() => notifier.send(user, msg)));
    return { out, store: storeDump(throttleStore) };
  });

  scenario(`throttle/zero-limit-falls-back-to-default/${channel}`, async () => {
    const { notifier } = env(channel, { maxPerHour: 0 });
    const out = [];
    for (let i = 0; i < 10; i += 1) {
      const r = await capture(() => notifier.send(validUsers[channel], { title: 'T', body: 'B', category: 'digest' }));
      out.push(r.value ? r.value.status : r);
    }
    return out;
  });

  scenario(`throttle/isolation-by-user-and-category/${channel}`, async () => {
    const { notifier, throttleStore } = env(channel, { maxPerHour: 1 });
    const user = validUsers[channel];
    const other = { ...user, id: `${user.id}-other` };
    const out = [];
    out.push(await capture(() => notifier.send(user, { title: 'T', body: 'B' })));
    out.push(await capture(() => notifier.send(user, { title: 'T', body: 'B', category: 'general' })));
    out.push(await capture(() => notifier.send(user, { title: 'T', body: 'B', category: 'release' })));
    out.push(await capture(() => notifier.send(other, { title: 'T', body: 'B' })));
    out.push(await capture(() => notifier.send(user, { title: 'T', body: 'B', category: 'release' })));
    return { out, store: storeDump(throttleStore) };
  });

  scenario(`throttle/force-and-urgent-bypass/${channel}`, async () => {
    const { notifier, now, throttleStore } = env(channel, { maxPerHour: 1 });
    const user = validUsers[channel];
    const msg = { title: 'T', body: 'B', category: 'digest' };
    const out = [];
    out.push(await capture(() => notifier.send(user, msg)));
    out.push(await capture(() => notifier.send(user, msg)));
    const before = now.calls;
    out.push(await capture(() => notifier.send(user, msg, { force: true })));
    out.push(now.calls - before);
    out.push(await capture(() => notifier.send(user, { ...msg, priority: 'urgent' })));
    out.push(await capture(() => notifier.send(user, msg, { force: 0 })));
    return { out, store: storeDump(throttleStore) };
  });

  scenario(`throttle/shouldThrottle-direct/${channel}`, async () => {
    const { notifier } = env(channel, { maxPerHour: 1 });
    const user = validUsers[channel];
    const msg = { title: 'T', body: 'B', category: 'digest' };
    await notifier.send(user, msg);
    return [
      captureSync(() => notifier.shouldThrottle(user, msg)),
      captureSync(() => notifier.shouldThrottle(user, msg, { force: true })),
      captureSync(() => notifier.shouldThrottle(user, { ...msg, category: 'marketing' }))
    ];
  });

  scenario(`throttle/now-call-count/${channel}`, async () => {
    const { notifier, now } = env(channel, { maxPerHour: 1 });
    const user = validUsers[channel];
    const msg = { title: 'T', body: 'B', category: 'digest' };
    const counts = [];
    let before = now.calls;
    await notifier.send(user, msg);
    counts.push(now.calls - before);
    before = now.calls;
    await notifier.send(user, msg);
    counts.push(now.calls - before);
    before = now.calls;
    await notifier.send(user, msg, { force: true });
    counts.push(now.calls - before);
    before = now.calls;
    await notifier.send(user, { ...msg, category: 'security' });
    counts.push(now.calls - before);
    before = now.calls;
    await notifier.send(user, msg, { threadTs: '1.2' });
    counts.push(now.calls - before);
    return counts;
  });
}

for (const [channel, flag] of [['email', 'emailOptIn'], ['sms', 'smsOptIn']]) {
  scenario(`throttle/marketing-consent/${channel}`, async () => {
    const { notifier, transport, throttleStore } = env(channel, { maxPerHour: 1 });
    const optedOut = { ...validUsers[channel], id: 'out', [flag]: false };
    const optedIn = { ...validUsers[channel], id: 'in', [flag]: true };
    const marketing = { title: 'Deal', body: 'Save', category: 'marketing' };
    const out = [];
    out.push(await capture(() => notifier.send(optedOut, marketing)));
    out.push(await capture(() => notifier.send(optedOut, marketing, { force: true })));
    out.push(await capture(() => notifier.send(optedOut, { ...marketing, priority: 'urgent' })));
    out.push(await capture(() => notifier.send(optedIn, marketing)));
    out.push(await capture(() => notifier.send(optedIn, marketing)));
    // Rate limit wins over consent when both apply.
    throttleStore.set(`${channel}:out:marketing`, [new Date(START).getTime()]);
    out.push(await capture(() => notifier.send(optedOut, marketing)));
    out.push(await capture(() => notifier.send({ ...optedOut, [flag]: 'truthy' }, { ...marketing, category: 'other' })));
    return { out, calls: transport.calls.length, store: storeDump(throttleStore) };
  });
}

scenario('throttle/marketing-consent-not-applied-to-slack-inapp', async () => {
  const out = [];
  for (const channel of ['slack', 'inapp']) {
    const { notifier } = env(channel);
    out.push(await capture(() => notifier.send(validUsers[channel], { title: 'Deal', body: 'Save', category: 'marketing' })));
  }
  return out;
});

scenario('throttle/slack-thread-bypass', async () => {
  const { notifier, throttleStore } = env('slack', { maxPerHour: 1 });
  const user = validUsers.slack;
  const msg = { title: 'T', body: 'B' };
  const out = [];
  out.push(await capture(() => notifier.send(user, msg)));
  out.push(await capture(() => notifier.send(user, msg)));
  out.push(await capture(() => notifier.send(user, msg, { threadTs: '171234.0001' })));
  out.push(await capture(() => notifier.send(user, msg, { threadTs: '' })));
  return { out, store: storeDump(throttleStore) };
});

scenario('throttle/inapp-security-bypass', async () => {
  const { notifier, throttleStore } = env('inapp', { maxPerHour: 1 });
  const user = validUsers.inapp;
  const out = [];
  for (let i = 0; i < 3; i += 1) {
