const DEFAULT_CATEGORY = 'general';
const URGENT_PRIORITY = 'urgent';

/**
 * Checks shared by every channel. Channel strategies add their own recipient
 * checks, which run only after these pass.
 * @throws {TypeError}
 */
function validateUser(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

/** @throws {TypeError} */
function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

/** Category used for throttle keys, templates and payload metadata. */
function categoryOf(message) {
  return message.category || DEFAULT_CATEGORY;
}

function isUrgent(message) {
  return message.priority === URGENT_PRIORITY;
}

module.exports = {
  validateUser,
  validateMessage,
  categoryOf,
  isUrgent
};

