const { categoryOf } = require('./inputs');

const WINDOW_MS = 60 * 60 * 1000;

/**
 * Hourly send limit per channel, user and message category.
 *
 * `store` is caller-owned and may be shared between notifiers, which is why
 * keys are prefixed with the channel. Records are appended as-is; timestamps
 * older than the window are ignored when counting, not removed.
 *
 * @param {object} config
 * @param {string} config.channel
 * @param {Map<string, number[]>} config.store
 * @param {number} config.maxPerHour
 * @param {() => Date} config.now
 */
function createRateLimiter({ channel, store, maxPerHour, now }) {
  function keyFor(user, message) {
    return `${channel}:${user.id}:${categoryOf(message)}`;
  }

  function check(user, message) {
    const key = keyFor(user, message);
    const currentMs = now().getTime();
    const recent = (store.get(key) || []).filter(ts => currentMs - ts < WINDOW_MS);

    if (recent.length >= maxPerHour) {
      return {
        throttled: true,
        reason: `${channel} hourly limit reached`,
        retryAt: new Date(recent[0] + WINDOW_MS).toISOString()
      };
    }

    return { throttled: false };
  }

  function record(user, message) {
    const key = keyFor(user, message);
    const records = store.get(key) || [];
    records.push(now().getTime());
    store.set(key, records);
  }

  return { check, record };
}

/**
 * Consent check that holds back marketing messages unless `user[optInField]`
 * is truthy. The result has the same shape as a rate-limit decision.
 *
 * @param {string} optInField - user property that records consent, e.g. `emailOptIn`
 * @param {string} audience - wording for the reason, e.g. `email` or `SMS`
 */
function requireMarketingOptIn(optInField, audience) {
  return function checkMarketingConsent(user, message) {
    if (message.category === 'marketing' && !user[optInField]) {
      return {
        throttled: true,
        reason: `user has not opted into marketing ${audience}`,
        retryAt: null
      };
    }
    return { throttled: false };
  };
}

module.exports = {
  createRateLimiter,
  requireMarketingOptIn
};

