const mutants = [
  ['consent before rate limit', 'channelNotifier.js', "    if (!exempt) {\n      const limit", "    const early = checkConsent(user, message); if (early.throttled) return early;\n    if (!exempt) {\n      const limit"],
  ['base exemption checked before channel bypass', 'channelNotifier.js', "const exempt = bypassRateLimit(user, message, sendOptions)\n      || sendOptions.force\n      || inputs.isUrgent(message);", "const exempt = sendOptions.force || inputs.isUrgent(message) || bypassRateLimit(user, message, sendOptions);"],
  ['detached transport call loses this', 'transport.js', 'await transport[key](payload);', 'const fn = transport[key]; await fn(payload);'],
  ['record before deliver', 'channelNotifier.js', "    await deliver(payload);\n    rateLimiter.record(user, message);", "    rateLimiter.record(user, message);\n    await deliver(payload);"],
  ['merge order reversed', 'channelNotifier.js', "      ...base,\n      ...extendPayload(base, { user, message, options: sendOptions, now })", "      ...extendPayload(base, { user, message, options: sendOptions, now }),\n      ...base"],
  ['inapp reuses generatedAt clock read', 'channels/inapp.js', 'new Date(now().getTime() +', 'new Date(Date.parse(base.metadata.generatedAt) +'],
  ['sms segment off-by-one', 'channels/sms.js', 'value.length <= segmentLength', 'value.length < segmentLength'],
  ['email escape drops quotes', 'channels/email.js', ".replace(/\"/g, '&quot;')", ''],
  ['stale entries pruned on record', 'throttling.js', "const records = store.get(key) || [];", "const records = (store.get(key) || []).filter(ts => now().getTime() - ts < WINDOW_MS);"],
  ['send results drop retryAt', 'channelNotifier.js', 'retryAt: throttle.retryAt,', ''],
  ['maxPerHour ?? instead of ||', 'channels/sms.js', 'options.maxPerHour || DEFAULT_MAX_PER_HOUR', 'options.maxPerHour ?? DEFAULT_MAX_PER_HOUR'],
  ['validateMessage before validateUser', 'channelNotifier.js', "    validateUser(user);\n    inputs.validateMessage(message);", "    inputs.validateMessage(message);\n    validateUser(user);"]
];
let survived = 0;
for (const [name, file, from, to] of mutants) {
  const dir = fs.mkdtempSync(path.join(process.cwd(), 'mutant-'));
  fs.cpSync(src, dir, { recursive: true });
  const target = path.join(dir, file);
  const code = fs.readFileSync(target, 'utf8');
  if (!code.includes(from)) { console.log(`SKIP (pattern missing): ${name}`); survived += 1; continue; }
  fs.writeFileSync(target, code.replace(from, to));
  const out = path.join(dir, 'out.json');
  fs.writeFileSync(out, execFileSync('node', ['characterize.js', dir]));
  let killed = false;
  try { execFileSync('node', ['compare.js', 'golden.json', out], { stdio: 'pipe' }); } catch (e) { killed = true; var detail = String(e.stdout).match(/(\d+) differ/)[1]; }
  console.log(`${killed ? 'KILLED  ' : 'SURVIVED'} ${name}${killed ? ` (${detail} scenarios differ)` : ''}`);
  if (!killed) survived += 1;
  fs.rmSync(dir, { recursive: true, force: true });
}
console.log(`${mutants.length - survived}/${mutants.length} mutants killed`);
EOF
